import{_ as a,o as r,c as i,ae as t}from"./chunks/framework.Dh1jimFm.js";const f=JSON.parse('{"title":"Performance Tips","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/performance.md","filePath":"troubleshooting/performance.md"}'),s={name:"troubleshooting/performance.md"};function l(o,e,n,p,c,h){return r(),i("div",null,e[0]||(e[0]=[t('<h1 id="performance-tips" tabindex="-1">Performance Tips <a class="header-anchor" href="#performance-tips" aria-label="Permalink to &quot;Performance Tips&quot;">​</a></h1><p>Supervertaler is designed to stay responsive on large projects, but performance can vary with project size and enabled features.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Enable <a href="./../editor/pagination.html">Pagination</a> for very large projects</li><li>Use a smaller <strong>segments per page</strong> setting (for example 50)</li><li>Keep only the needed TMs and glossaries enabled</li><li>If semantic search is enabled, allow indexing to complete</li></ul><h2 id="quick-wins-when-it-feels-slow" tabindex="-1">Quick wins when it feels slow <a class="header-anchor" href="#quick-wins-when-it-feels-slow" aria-label="Permalink to &quot;Quick wins when it feels slow&quot;">​</a></h2><ol><li>Disable spellcheck temporarily (Settings → View Settings)</li><li>Disable Supermemory/semantic features if you don’t need them</li><li>Close other heavy apps (browsers with many tabs, IDE builds, etc.)</li><li>Restart Supervertaler and reopen the project</li></ol><h2 id="large-projects" tabindex="-1">Large projects <a class="header-anchor" href="#large-projects" aria-label="Permalink to &quot;Large projects&quot;">​</a></h2><p>Very large files (thousands of segments) can stress any UI grid.</p><ul><li>Prefer pagination.</li><li>Consider splitting source documents or using multi-file projects.</li></ul><h2 id="if-it-feels-slow" tabindex="-1">If it feels slow <a class="header-anchor" href="#if-it-feels-slow" aria-label="Permalink to &quot;If it feels slow&quot;">​</a></h2><p>Try restarting the app and reopening the project.</p><p>If performance is still poor, note:</p><ul><li>Project size (segment count)</li><li>Whether spellcheck is enabled</li><li>Whether Supermemory is enabled</li><li>Which CAT format you imported</li></ul>',13)]))}const m=a(s,[["render",l]]);export{f as __pageData,m as default};
